/**
 * E2E tests for file converter tools.
 *
 * These tests go beyond "does the page load" — they verify:
 *  - File upload triggers extraction/parsing
 *  - Preview shows real content from the input file
 *  - Download button is clickable and triggers a download
 *  - Downloaded file has non-zero size
 *  - Downloaded file contains expected content (where parseable)
 *
 * Test fixtures live in tests/fixtures/ (file-tool regression fixtures in
 * tests/fixtures/file-tools/, regenerated by generate.mjs there).
 *
 * Google Analytics is blocked in every test (the built HTML carries the
 * production tag). Set FILE_TOOLS_PROD_HEADERS=1 to re-apply public/_headers
 * (CSP etc.) to every response, the way Cloudflare does in production; the
 * HEIC test must pass with it on (review FILES-01: dev and preview servers
 * ignore _headers, which is how the HEIC CSP breakage shipped unnoticed).
 */
import { test, expect, type Page, type Download } from '@playwright/test';
import path from 'path';
import fs from 'fs';
import os from 'os';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const FIXTURES = path.join(__dirname, 'fixtures');
const FT = path.join(FIXTURES, 'file-tools');
const GA_RE = /(googletagmanager|google-analytics|analytics\.google|doubleclick)\.(com|net)/;

// ---- optional production-header emulation (accumulate + "!" detach, as Cloudflare does) ----
type HeaderRule = { pattern: RegExp; set: Array<[string, string]>; detach: string[] };
function parseHeadersFile(): HeaderRule[] {
  const txt = fs.readFileSync(path.join(__dirname, '..', 'public', '_headers'), 'utf8');
  const rules: HeaderRule[] = [];
  let cur: HeaderRule | null = null;
  for (const raw of txt.split(/\r?\n/)) {
    if (!raw.trim() || raw.trim().startsWith('#')) continue;
    if (!/^\s/.test(raw)) {
      const pat = raw.trim().replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
      cur = { pattern: new RegExp(`^${pat}$`), set: [], detach: [] };
      rules.push(cur);
      continue;
    }
    const line = raw.trim();
    if (!cur) continue;
    if (line.startsWith('!')) { cur.detach.push(line.slice(1).trim().toLowerCase()); continue; }
    const i = line.indexOf(':');
    cur.set.push([line.slice(0, i).trim().toLowerCase(), line.slice(i + 1).trim()]);
  }
  return rules;
}
const HEADER_RULES = process.env.FILE_TOOLS_PROD_HEADERS ? parseHeadersFile() : [];
function headersFor(pathname: string, upgradeInsecure = true): Record<string, string> {
  const out: Record<string, string> = {};
  for (const r of HEADER_RULES) {
    if (!r.pattern.test(pathname)) continue;
    for (const d of r.detach) delete out[d];
    for (const [k, v] of r.set) out[k] = out[k] ? `${out[k]}, ${v}` : v;
  }
  // WebKit (unlike Chromium and Firefox) applies upgrade-insecure-requests to http://127.0.0.1,
  // so the test server's own scripts would be fetched over https and fail. Production is https
  // already, where the directive changes nothing; drop it only from the local emulation.
  if (!upgradeInsecure && out['content-security-policy']) {
    out['content-security-policy'] = out['content-security-policy'].replace(/;\s*upgrade-insecure-requests/g, '');
  }
  return out;
}

test.beforeEach(async ({ context, baseURL, browserName }) => {
  await context.route(GA_RE, (route) => route.abort());
  // Keep the cookie banner from covering tool controls (it sits over the left column).
  await context.addInitScript(() => {
    const hide = () => {
      const style = document.createElement('style');
      style.textContent = '#cookie-banner{display:none!important}';
      (document.head || document.documentElement)?.appendChild(style);
    };
    if (document.documentElement) hide();
    else document.addEventListener('DOMContentLoaded', hide);
  });
  if (HEADER_RULES.length > 0 && baseURL) {
    const origin = new URL(baseURL).origin;
    // http(s) only: a blob: URL's origin is the page origin, and WebKit routes blob: loads
    // through interception, where route.fetch() cannot follow them (it aborted SVG images
    // and the HEIC decoder worker in WebKit only).
    const matches = (url: URL) => (url.protocol === 'http:' || url.protocol === 'https:')
      && url.origin === origin && !url.pathname.startsWith('/api/');
    await context.route(matches, async (route) => {
      try {
        const res = await route.fetch();
        const pathname = new URL(route.request().url()).pathname;
        await route.fulfill({ response: res, headers: { ...res.headers(), ...headersFor(pathname, browserName !== 'webkit') } });
      } catch {
        // The page closed mid-request (prefetch); nothing to fulfil.
        await route.abort().catch(() => undefined);
      }
    });
  }
});

test.afterEach(async ({ context }) => {
  await context.unrouteAll({ behavior: 'ignoreErrors' });
});

/** Upload a single file via the FileDropZone input */
async function uploadFile(page: Page, filePath: string) {
  const fileInput = page.locator('input[type="file"]').first();
  await fileInput.setInputFiles(filePath);
}

/** Upload multiple files */
async function uploadFiles(page: Page, filePaths: string[]) {
  const fileInput = page.locator('input[type="file"]').first();
  await fileInput.setInputFiles(filePaths);
}

/** Wait for processing spinners to disappear */
async function waitForProcessing(page: Page, timeout = 30000) {
  await page.waitForFunction(
    () => {
      const text = document.body.innerText;
      return (
        !text.includes('Converting...') &&
        !text.includes('Generating...') &&
        !text.includes('Processing...') &&
        !text.includes('Reading Word') &&
        !text.includes('Extracting text')
      );
    },
    { timeout }
  );
}

/**
 * Click a download button and wait for the download event.
 * Returns the Download object so we can inspect the file.
 */
async function clickAndWaitForDownload(
  page: Page,
  buttonLocator: ReturnType<Page['getByRole']>
): Promise<Download> {
  const [download] = await Promise.all([
    page.waitForEvent('download', { timeout: 30000 }),
    buttonLocator.click(),
  ]);
  return download;
}

/**
 * Save a download to a temp path and return the path + file size.
 */
async function saveDownload(download: Download): Promise<{ path: string; size: number }> {
  const tmpPath = path.join(os.tmpdir(), `test-download-${Date.now()}-${download.suggestedFilename()}`);
  await download.saveAs(tmpPath);
  const stats = fs.statSync(tmpPath);
  return { path: tmpPath, size: stats.size };
}

