// ════════════════════════════════════════════════════════════════
//  FILE-TOOL REGRESSIONS (review FILES-01..23, plan W1-FILES FI-1..FI-13)
// ════════════════════════════════════════════════════════════════

/** Tool messages only (the cookie banner is also role="alert"). */
function toolAlert(page: Page, text: string | RegExp) {
  return page.locator('[role="alert"]:not(#cookie-banner)').filter({ hasText: text }).first();
}

/** Upload `files` and wait for a download triggered by clicking `button`. */
async function downloadBytes(page: Page, click: () => Promise<unknown>): Promise<{ name: string; bytes: Buffer }> {
  const [download] = await Promise.all([page.waitForEvent('download', { timeout: 60000 }), click()]);
  const saved = await saveDownload(download);
  return { name: download.suggestedFilename(), bytes: fs.readFileSync(saved.path) };
}

/** The size a browser DISPLAYS `bytes` at (naturalWidth/Height applies the Orientation tag where honoured). */
async function displayedSize(page: Page, bytes: Buffer, type: string): Promise<{ w: number; h: number }> {
  return page.evaluate(async ({ b64, mime }) => {
    const bin = atob(b64);
    const data = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) data[i] = bin.charCodeAt(i);
    const url = URL.createObjectURL(new Blob([data], { type: mime }));
    try {
      const img = new Image();
      img.src = url;
      await img.decode();
      return { w: img.naturalWidth, h: img.naturalHeight };
    } finally {
      URL.revokeObjectURL(url);
    }
  }, { b64: bytes.toString('base64'), mime: type });
}

async function rgbAt(bytes: Buffer, x: number, y: number): Promise<number[]> {
  const sharp = (await import('sharp')).default;
  const { data, info } = await sharp(bytes).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  const i = (Math.round(y) * info.width + Math.round(x)) * 3;
  return [data[i], data[i + 1], data[i + 2]];
}

function near(actual: number[], expected: number[], tolerance = 40) {
  actual.forEach((v, i) => expect(Math.abs(v - expected[i]), `channel ${i}: ${actual} vs ${expected}`).toBeLessThanOrEqual(tolerance));
}

test.describe('HEIC to JPG converts (FILES-01, S1-12)', () => {
  test('a HEIC photo converts to a correct JPG (run with FILE_TOOLS_PROD_HEADERS=1 for the production CSP)', async ({ page }) => {
    const cspErrors: string[] = [];
    page.on('console', (m) => { if (/Content Security Policy|Refused to/i.test(m.text())) cspErrors.push(m.text()); });
    await page.goto('/tools/file-tools/heic-to-jpg/');
    await page.waitForLoadState('networkidle');
    await uploadFile(page, path.join(FT, 'quadrants-256x128.heic'));
    await expect(page.getByText(/1\s+file converted/)).toBeVisible({ timeout: 90000 });
    await expect(page.getByText(/not supported|Chrome 128/i)).toHaveCount(0);
    const { name, bytes } = await downloadBytes(page, () => page.getByRole('button', { name: /download quadrants-256x128\.jpg/i }).click());
    expect(name).toBe('quadrants-256x128.jpg');
    expect(bytes.subarray(0, 3).toString('hex')).toBe('ffd8ff');
    near(await rgbAt(bytes, 64, 64), [214, 40, 40]); // red half
    near(await rgbAt(bytes, 192, 32), [29, 78, 216]); // blue quarter
    near(await rgbAt(bytes, 192, 96), [22, 163, 74]); // green quarter
    expect(cspErrors).toEqual([]);
  });

  test('a file that is not HEIC gets a clear, browser-neutral error', async ({ page }) => {
    await page.goto('/tools/file-tools/heic-to-jpg/');
    await page.waitForLoadState('networkidle');
    await page.locator('input[type="file"]').first().setInputFiles({ name: 'broken.heic', mimeType: 'image/heic', buffer: Buffer.from('not really a heic file') });
    await expect(toolAlert(page, 'could not be decoded')).toBeVisible({ timeout: 60000 });
    await expect(page.getByText(/Chrome 128/)).toHaveCount(0);
  });
});

test.describe('Encrypted PDFs are refused (FILES-02, S1-13)', () => {
  const ENCRYPTED = ['enc-owner-only-aes128.pdf', 'enc-owner-only-aes256.pdf', 'enc-owner-only-rc4.pdf', 'enc-user-pw-aes128.pdf', 'enc-owner-only-photo.pdf'];

  test('PDF Compress refuses all five encrypted fixtures with a workaround', async ({ page }) => {
    await page.goto('/tools/file-tools/pdf-compress/');
    await page.waitForLoadState('networkidle');
    for (const f of ENCRYPTED) {
      await uploadFile(page, path.join(FT, f));
      await expect(toolAlert(page, f)).toContainText('is encrypted', { timeout: 15000 });
      await expect(toolAlert(page, f)).toContainText('Save as PDF');
      await expect(page.getByRole('button', { name: /compress pdf/i })).toHaveCount(0);
    }
  });

  test('PDF Merge names the encrypted file and does not add it', async ({ page }) => {
    await page.goto('/tools/file-tools/pdf-merge/');
    await page.waitForLoadState('networkidle');
    await uploadFiles(page, [path.join(FT, 'text-3p.pdf'), path.join(FT, 'enc-owner-only-aes128.pdf')]);
    await expect(toolAlert(page, '"enc-owner-only-aes128.pdf" is encrypted')).toBeVisible({ timeout: 15000 });
    await expect(page.getByText(/1 PDF — 3 total pages/)).toBeVisible();
  });

  test('PDF Split refuses an owner-password-only PDF', async ({ page }) => {
    await page.goto('/tools/file-tools/pdf-split/');
    await page.waitForLoadState('networkidle');
    await uploadFile(page, path.join(FT, 'enc-owner-only-rc4.pdf'));
    await expect(toolAlert(page, 'is encrypted')).toBeVisible({ timeout: 15000 });
    await expect(page.getByRole('button', { name: /extract|split/i })).toHaveCount(0);
  });
});

test.describe('PDF tools use the JavaScript decoders, never WebAssembly', () => {
  // The site CSP has no 'wasm-unsafe-eval', so a WebAssembly module pdf.js asked for was downloaded and then
  // refused (and logged an error). With useWasm off, no .wasm file is requested and nothing is refused.
  // Run with FILE_TOOLS_PROD_HEADERS=1 so the production CSP applies and a regression would also log refusals.
  function watchWasm(page: Page) {
    const requests: string[] = [];
    const complaints: string[] = [];
    page.on('request', (r) => { if (/\.wasm(\?|$)/i.test(r.url())) requests.push(r.url()); });
    page.on('console', (m) => {
      const t = m.text();
      if (/Refused to compile or instantiate WebAssembly|blocked by CSP|instantiateWasm|WebAssembly/i.test(t)) complaints.push(t.slice(0, 200));
    });
    return { requests, complaints };
  }

  /** Convert `fixture` to PNG (scale 1) and return the first page's pixels. */
  async function renderFirstPage(page: Page, fixture: string): Promise<Buffer> {
    await page.goto('/tools/file-tools/pdf-to-image/');
    await page.waitForLoadState('networkidle');
    await uploadFile(page, path.join(FT, fixture));
    await page.locator('#img-format').selectOption('image/png');
    await page.getByRole('button', { name: /convert to png/i }).click();
    await expect(page.getByText(/1 page converted/)).toBeVisible({ timeout: 60000 });
    return (await downloadBytes(page, () => page.getByRole('button', { name: /download page 1/i }).click())).bytes;
  }

  test('PDF to Image: JPEG 2000, JBIG2 and ICC-based images render with 0 .wasm requests and 0 refusals', async ({ page }) => {
    const seen = watchWasm(page);
    // JPEG 2000 (OpenJPEG): the image's middle band is red (see the JPEG 2000 test above).
    near(await rgbAt(await renderFirstPage(page, 'jpx-image.pdf'), 500, (842 - 620) * 2), [220, 60, 40], 60);
    // JBIG2 (pdf.js's built-in JavaScript decoder): an 8x8 black square in the middle of a 24x24 image on a 240pt page, rendered at 2x.
    const jbig2 = await renderFirstPage(page, 'jbig2.pdf');
    near(await rgbAt(jbig2, 240, 240), [0, 0, 0], 40);
    near(await rgbAt(jbig2, 20, 20), [255, 255, 255], 10);
    near(await rgbAt(jbig2, 460, 460), [255, 255, 255], 10);
    // ICC-based RGB (alternate device colour space): left half red, right half blue.
    const icc = await renderFirstPage(page, 'icc-rgb.pdf');
    near(await rgbAt(icc, 120, 240), [200, 40, 40], 30);
    near(await rgbAt(icc, 360, 240), [40, 40, 200], 30);
    expect(seen.requests).toEqual([]);
    expect(seen.complaints).toEqual([]);
  });

  test('PDF Compress, Merge and Split make 0 .wasm requests', async ({ page }) => {
    const seen = watchWasm(page);
    await page.goto('/tools/file-tools/pdf-compress/');
    await page.waitForLoadState('networkidle');
    await uploadFile(page, path.join(FT, 'flate-photo-2p.pdf'));
    await page.getByRole('button', { name: /compress pdf/i }).click();
    await expect(page.getByText(/2 of 2 images recompressed/)).toBeVisible({ timeout: 60000 });
    await page.goto('/tools/file-tools/pdf-merge/');
    await page.waitForLoadState('networkidle');
    await uploadFiles(page, [path.join(FT, 'form-2p.pdf'), path.join(FT, 'form-1p.pdf')]);
    await expect(page.getByText(/2 PDFs/)).toBeVisible({ timeout: 15000 });
    await page.goto('/tools/file-tools/pdf-split/');
    await page.waitForLoadState('networkidle');
    await uploadFile(page, path.join(FT, 'text-3p.pdf'));
    await page.locator('#page-range').fill('1-2');
    await expect(page.getByText('2 pages will be extracted into one PDF')).toBeVisible({ timeout: 15000 });
    expect(seen.requests).toEqual([]);
    expect(seen.complaints).toEqual([]);
  });
});

